/bin/zsh -lc "python3 -c 'from pathlib import Path
import csv,io,json,re,ipaddress,collections
from datetime import datetime
p=Path(\"Semana12/logs_sinteticos.csv\")
b=p.read_bytes()
reader=csv.DictReader(io.StringIO(b.decode(\"utf-8-sig\"),newline=\"\"))
rows=[]
errors=[]
for x in reader:
    row=dict(x)
    row[\"fila\"]=reader.line_num
    try:
        row[\"_t\"]=datetime.fromisoformat(row[\"timestamp\"].replace(\"Z\",\"+00:00\"))
    except ValueError:
        errors.append({\"fila\":row[\"fila\"],\"field\":\"timestamp\"})
    try:
        ipaddress.ip_address(row[\"ip\"])
    except ValueError:
        errors.append({\"fila\":row[\"fila\"],\"field\":\"ip\"})
    rows.append(row)
def safe(s):
    return re.sub(r\"\"\"(?i)(\\b(?:[\\w-]*token[\\w-]*|api[_-]?key|secret|password|authorization)\\b\\s*[=:]\\s*)(?:\"["'^"'"\\n]*\"|'\\''["'^'"'\\''\\n]*'\\''|["'^'"\\s,;\\n]+)\"\"\",lambda m:m.group(1)+\"[REDACTED]\",s)
def emit(x):
    print(safe(json.dumps(x,ensure_ascii=False,default=str)))
emit({\"validation_errors\":errors,\"timestamp_offsets\":sorted({str(x[\"_t\"].utcoffset()) for x in rows if \"_t\" in x}),\"empty_fields\":{k:sum(not x[k] for x in rows) for k in reader.fieldnames},\"event_result_counts\":dict(collections.Counter(x[\"event\"]+\"/\"+x[\"result\"] for x in rows))})
if not errors:
    ordered=sorted(rows,key=lambda x:(x[\"_t\"],x[\"fila\"]))
    emit({\"min_timestamp\":ordered[0][\"timestamp\"],\"max_timestamp\":ordered[-1][\"timestamp\"],\"input_chronological\":all(a[\"_t\"]<=b[\"_t\"] for a,b in zip(rows,rows[1:]))})
    for x in ordered:
        display={k:v for k,v in x.items() if k"'!="_t"}
        if re.search("token",display["detail"],re.I):
            display["detail"]="token=[REDACTED]"
        emit(display)
groups=collections.defaultdict(list)
for x in rows:
    groups[tuple(x[k] for k in reader.fieldnames)].append(x["fila"])
emit({"identical_row_groups":[v for v in groups.values() if len(v)>1]})
'"'"

